// Google Sheets : OAuth en mémoire seulement. Aucune écriture sans action explicite.
// La portée Sheets autorise l'accès à tous les tableurs : la limiter réellement
// au fichier choisi nécessite un flux Google Picker / drive.file distinct.
// Cette version ne change donc pas silencieusement les autorisations.
let sheetsAttempt=0,sheetsTimer=null;
function sheetsFinish(attempt,message){
 if(attempt!==sheetsAttempt)return;
 clearTimeout(sheetsTimer);sheetsTimer=null;sheetsStatus=message;render();
}
function sheetsConnect(){alert('Connexion Google Sheets désactivée dans cette version de test.');return;
 if(sheetsStatus==='Connexion en cours…')return;
 const attempt=++sheetsAttempt;
 sheetsStatus='Connexion en cours…';render();
 // Évite une attente sans fin si la fenêtre OAuth est fermée sans callback.
 sheetsTimer=setTimeout(()=>sheetsFinish(attempt,'Connexion non terminée. Réessaie ou annule la fenêtre Google.'),90000);
 googleLoad().then(()=>{
  if(attempt!==sheetsAttempt)return;
  const client=google.accounts.oauth2.initTokenClient({
   client_id:GOOGLE_CLIENT_ID,scope:SHEETS_SCOPE,
   callback:r=>{
    if(attempt!==sheetsAttempt)return;
    if(r.error||!r.access_token){sheetsFinish(attempt,'Connexion refusée ou annulée'+(r.error?' : '+r.error:''));return}
    sheetsToken=r.access_token;
    sheetsExpiry=Date.now()+Number(r.expires_in||3500)*1000;
    sheetsFinish(attempt,'Connecté · accès autorisé à Google Sheets');
   },
   error_callback:e=>sheetsFinish(attempt,'Fenêtre Google interrompue : '+(e?.type||'connexion annulée'))
  });
  client.requestAccessToken({prompt:'consent'});
 }).catch(e=>sheetsFinish(attempt,'Connexion impossible : '+e.message));
}
