// Navigation tactile horizontale, sans perturber le défilement vertical.
let swipeStart=null;
let swipeHandledAt=0;
document.addEventListener('click',ev=>{if(Date.now()-swipeHandledAt<500&&ev.target.closest('.agenda-swipe')){ev.preventDefault();ev.stopImmediatePropagation()}},true);
document.addEventListener('touchstart',ev=>{
 if(section!=='agenda'||modal||ev.touches.length!==1||!ev.target.closest('.agenda-swipe'))return;
 if(ev.target.closest('input,select,textarea,.modal'))return;
 const t=ev.touches[0];swipeStart={x:t.clientX,y:t.clientY,time:Date.now()};
},{passive:true});
document.addEventListener('touchend',ev=>{
 if(!swipeStart)return;
 const start=swipeStart;swipeStart=null;
 if(section!=='agenda'||modal||ev.changedTouches.length!==1)return;
 const t=ev.changedTouches[0],dx=t.clientX-start.x,dy=t.clientY-start.y;
 if(Math.abs(dx)<42||Math.abs(dx)<Math.abs(dy)*1.2||Date.now()-start.time>1800)return;
 swipeHandledAt=Date.now();
 const d=parseDate(state.selected),n=dx<0?1:-1;
 if(state.view==='three')d.setDate(d.getDate()+n);
 else if(state.view==='week')d.setDate(d.getDate()+7*n);
 else {const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+n);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));}
 state.selected=dateKey(d);save();render();
},{passive:true});
document.addEventListener('touchcancel',()=>{swipeStart=null},{passive:true});
document.addEventListener('submit',ev=>{if(ev.target.id!=='record-form')return;ev.preventDefault();const f=new FormData(ev.target),id=String(f.get('module'));if(!moduleDefs[id])return;const date=String(f.get('date')||''),title=String(f.get('title')||'').trim(),amount=String(f.get('amount')||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!title||title.length>160||amount&&(!Number.isFinite(Number(amount))||Math.abs(Number(amount))>100000000)){alert('Vérifie les valeurs.');return}const entry={id:modal.record||uid(),date,title,category:String(f.get('category')||'').slice(0,120),type:String(f.get('type')||'').slice(0,60),amount,payment:id==='budget'?String(f.get('payment')||''):undefined,notes:String(f.get('notes')||'').slice(0,2000)};const items=moduleRecords(id),idx=items.findIndex(x=>x.id===entry.id);if(idx>=0)items[idx]=entry;else items.push(entry);save();modal=null;section=id;render()});
